var updateHeadingIDs = flag.Bool("update-heading-ids", false, "rewrite the legacy heading id golden")

// TestTodaysHeadingIDsStillResolve pins every heading id a note written before
// the Unicode rule could have named. The golden is deliberately generated by
// goldmark's default IDs, not view's shared rule, so it cannot drift when that
// rule changes. Every pinned id must still resolve to the heading that owned it.
func TestTodaysHeadingIDsStillResolve(t *testing.T) {
	files, err := filepath.Glob("testdata/docs/*.md")
	if err != nil {
		t.Fatalf("glob: %v", err)
	}
	type note struct{ name, source string }
	var notes []note
	for _, name := range files {
		raw, err := os.ReadFile(name)
		if err != nil {
			t.Fatalf("read %s: %v", name, err)
		}
		notes = append(notes, note{filepath.Base(name), stripFrontMatter(string(raw))})
	}
	notes = append(notes, note{"live-heading-id-note.md", "# Where a heading id comes from\n\n## Who decides\n\n## What the reader gets\n"})

	var lines []string
	for _, n := range notes {
		source := []byte(n.source)
		pc := parser.NewContext(parser.WithIDs(view.NewHeadingIDs()))
		root := parse().Parser().Parse(text.NewReader(source), parser.WithContext(pc))
		anchors, err := headingAnchors(root, source)
		if err != nil {
			t.Fatalf("collect %s anchors: %v", n.name, err)
		}
		legacy := parser.NewContext().IDs()
		_ = ast.Walk(root, func(node ast.Node, entering bool) (ast.WalkStatus, error) {
			if !entering {
				return ast.WalkContinue, nil
			}
			heading, ok := node.(*ast.Heading)
			if !ok {
				return ast.WalkContinue, nil
			}
			segment := heading.Lines().At(heading.Lines().Len() - 1)
			line := segment.Value(source)
			id := string(legacy.Generate(line, ast.KindHeading))
			if insideFootnote(heading) || isFigureOnly(heading, source) {
				return ast.WalkContinue, nil
			}
			lines = append(lines, fmt.Sprintf("%s\t%s", n.name, id))
			newRaw, _ := heading.AttributeString("id")
			newID := string(newRaw.([]byte))
			if anchors[id] != bookmarkName(newID) {
				t.Errorf("%s heading %q: legacy id %q does not resolve", n.name, heading.Text(source), id)
			}
			if isASCII(string(line)) && !strings.Contains(string(line), "_") && newID != id {
				t.Errorf("%s ASCII heading %q: new id %q moved from %q", n.name, line, newID, id)
			}
			return ast.WalkContinue, nil
		})
	}
	got := strings.Join(lines, "\n") + "\n"
	golden := filepath.Join("testdata", "golden", "heading-ids.txt")
	if *updateHeadingIDs {
		if err := os.WriteFile(golden, []byte(got), 0o644); err != nil {
			t.Fatalf("write %s: %v", golden, err)
		}
	}
	want, err := os.ReadFile(golden)
	if err != nil {
		t.Fatalf("read %s: %v (run with -update-heading-ids to write it)", golden, err)
	}
	if got != string(want) {
		t.Errorf("today's heading ids moved; run with -update-heading-ids only before changing the id rule")
	}
}

// TestBookmarkNameIsWordSafe pins the rewrite, which is wider than anything
// goldmark's own generator emits: Word takes letters, digits and underscores
// only, and at most 40 characters. The name opens with "_h_", because Drive's
// import mints the heading id only from a bookmark whose name opens with an
// underscore, and Word hides a bookmark that does.
func TestBookmarkNameIsWordSafe(t *testing.T) {
	for _, c := range []struct{ id, want string }{
		{"purpose-and-scope", "_h_purpose_and_scope"},
		{"1-1-purpose", "_h_1_1_purpose"},
		{"a.b", "_h_a_b"},
	} {
		if got := bookmarkName(c.id); got != c.want {
			t.Errorf("bookmarkName(%q) is %q, want %q", c.id, got, c.want)
		}
	}

	long := bookmarkName("what-counts-as-outsourcing-and-why-it-matters")
	if len(long) != 40 {
		t.Errorf("the long name is %d characters, want Word's ceiling of 40: %q",
			len(long), long)
	}
	if prefix := "_h_what_counts_as_outsourcing_an"; !strings.HasPrefix(long, prefix) {
		t.Errorf("the long name is %q, want it to open with %q", long, prefix)
	}
	if want := "_h_what_counts_as_outsourcing_an_9cccf62"; long != want {
		t.Errorf("the long name is %q, want %q", long, want)
	}
	for _, id := range []string{"цели-проекта", "a_b"} {
		if got := bookmarkName(id); !regexp.MustCompile(`^_h_[0-9a-f]{7}$`).MatchString(got) {
			t.Errorf("bookmarkName(%q) = %q, want a short ASCII hash", id, got)
		}
	}
}

func TestALinkToACyrillicHeadingIsAJump(t *testing.T) {
	out := walk(t, "## Цели проекта\n\n[goals](#цели-проекта)\n")
	links := hyperlinkAnchors(t, out)
	if len(links) != 1 || !regexp.MustCompile(`^_h_[0-9a-f]{7}$`).MatchString(links[0]) {
		t.Fatalf("link anchors = %v, want one hashed bookmark", links)
	}
	if !strings.Contains(serialise(t, out.Blocks), `w:name="`+links[0]+`"`) {
		t.Errorf("the link names %q, but no heading carries it", links[0])
	}
	if len(out.Warnings) != 0 {
		t.Errorf("resolved Cyrillic link warns: %v", out.Warnings)
	}
}

func TestTwoOneWordRussianHeadingsAreTwoIDs(t *testing.T) {
	out := walk(t, "[goals](#цели) [risks](#риски)\n\n# Цели\n\n# Риски\n")
	assertTwoDifferentJumps(t, out)
}

func TestARepeatedCyrillicHeadingTakesASuffix(t *testing.T) {
	out := walk(t, "[first](#итоги) [second](#итоги-1)\n\n## Итоги\n\n## Итоги\n")
	assertTwoDifferentJumps(t, out)
}

// TestARepeatedHeadingsLinkIsTheIDBodyCollects walks the projection itself:
// both links must resolve without warning and land on different bookmarks.
func TestARepeatedHeadingsLinkIsTheIDBodyCollects(t *testing.T) {
	d := &docs.Document{Tabs: []docs.Tab{{Body: []docs.Block{
		{Paragraph: &docs.Paragraph{Style: "HEADING_2", HeadingID: "h.a", Runs: []docs.Run{{Kind: docs.KindText, Text: "Scope"}}}},
		{Paragraph: &docs.Paragraph{Style: "HEADING_2", HeadingID: "h.b", Runs: []docs.Run{{Kind: docs.KindText, Text: "Scope"}}}},
		{Paragraph: &docs.Paragraph{Style: "NORMAL_TEXT", Runs: []docs.Run{
			{Kind: docs.KindText, Text: "first", Link: &docs.Link{HeadingID: "h.a"}},
			{Kind: docs.KindText, Text: " and "},
			{Kind: docs.KindText, Text: "second", Link: &docs.Link{HeadingID: "h.b"}},
		}}},
	}}}}
	markdown, warnings := view.Text(d)
	if len(warnings) != 0 {
		t.Fatalf("projection warnings = %v, want none", warnings)
	}

	assertTwoDifferentJumps(t, walk(t, markdown))
}

func TestAnAccentedHeadingAnswersToBothIDs(t *testing.T) {
	out := walk(t, "[new](#résumé-of-änderungen-naïve-café) [old](#rsum-of-nderungen-nave-caf)\n\n## Résumé of Änderungen: naïve café\n")
	links := hyperlinkAnchors(t, out)
	if len(links) != 2 || links[0] != links[1] {
		t.Fatalf("link anchors = %v, want both ids to land on one bookmark", links)
	}
	if len(out.Warnings) != 0 {
		t.Errorf("an accented heading's aliases warn: %v", out.Warnings)
	}
}

func TestTwoHeadingsSharingABookmarkNameAreRefused(t *testing.T) {
	seen := map[string]string{}
	first, second := "", ""
	for i := 1; i <= 200000; i++ {
		id := fmt.Sprintf("я%d", i)
		name := bookmarkName(id)
		if prior, ok := seen[name]; ok {
			first, second = prior, id
			break
		}
		seen[name] = id
	}
	if first == "" {
		t.Fatal("no seven-hex-digit bookmark collision found in 200000 deterministic ids")
	}
	_, err := Render(config(t), []byte(fmt.Sprintf("# %s\n\n# %s\n", first, second)), "testdata/docs", true)
	if err == nil || !strings.Contains(err.Error(), first) || !strings.Contains(err.Error(), second) {
		t.Fatalf("Render collision error = %v, want both %q and %q", err, first, second)
	}
}

func TestAnUnderscoreAndAHyphenAreTwoBookmarks(t *testing.T) {
	out := walk(t, "[underscore](#a_b) [hyphen](#a-b)\n\n# a_b\n\n# a-b\n")
	assertTwoDifferentJumps(t, out)
}

func hyperlinkAnchors(t *testing.T, out Result) []string {
	t.Helper()
	var anchors []string
	for _, block := range out.Blocks {
		for _, link := range findAll(block, "w:hyperlink") {
			anchors = append(anchors, attr(t, link, "w:anchor"))
		}
	}
	return anchors
}

func assertTwoDifferentJumps(t *testing.T, out Result) {
	t.Helper()
	links := hyperlinkAnchors(t, out)
	if len(links) != 2 || links[0] == links[1] {
		t.Fatalf("link anchors = %v, want two different bookmarks", links)
	}
	body := serialise(t, out.Blocks)
	for _, link := range links {
		if !strings.Contains(body, `w:name="`+link+`"`) {
			t.Errorf("the link names %q, but no heading carries it", link)
		}
	}
	if len(out.Warnings) != 0 {
		t.Errorf("resolved links warn: %v", out.Warnings)
	}
}

// TestEveryHeadingCarriesAHiddenBookmark is the heading id's whole cause.
// Drive's docx import mints a Google heading id for a heading paragraph only
// when the paragraph carries a bookmark whose name opens with an underscore,
// and a contents entry is a link to a heading by that id. So every heading
// gdoc writes carries one empty pair before its first run, whether anything
// links to it or not, and Word hides such a bookmark from its own list.
//
// The pair is empty and sits before the runs, which is the shape Google's own
// docx export writes and the shape measured to mint an id.
func TestEveryHeadingCarriesAHiddenBookmark(t *testing.T) {
	out := walk(t, "# Purpose and scope\n\n## Background\n\n## Scope\n")
	got := serialise(t, out.Blocks)

	for _, want := range []string{
		"_h_purpose_and_scope", "_h_background", "_h_scope",
	} {
		if !strings.Contains(got, `w:name="`+want+`"`) {
			t.Errorf("no heading carries the bookmark %s:\n%s", want, got)
		}
	}

	headings := 0
	for i, block := range out.Blocks {
		starts := findAll(block, "w:bookmarkStart")
		if len(starts) == 0 {
			continue
		}
		headings++
		if len(starts) != 1 {
			t.Errorf("block %d opens %d bookmarks, want one", i, len(starts))
			continue
		}
		// The pair is this paragraph's own children, in order: the start,
		// its end directly after it, and only then the words.
		var tags []string
		for _, child := range block.ChildElements() {
			tags = append(tags, child.FullTag())
		}
		start, end, firstRun := -1, -1, -1
		for at, tag := range tags {
			switch tag {
			case "w:bookmarkStart":
				start = at
			case "w:bookmarkEnd":
				end = at
			case "w:r":
				if firstRun < 0 {
					firstRun = at
				}
			}
		}
		if end != start+1 {
			t.Errorf("block %d closes its bookmark at %d and opens it at %d, want the end directly after the start: %v",
				i, end, start, tags)
		}
		if firstRun >= 0 && firstRun < end {
			t.Errorf("block %d writes a run at %d before the bookmark's end at %d: %v",
				i, firstRun, end, tags)
		}
		if id := attr(t, starts[0], "w:id"); id != attr(t, findAll(block, "w:bookmarkEnd")[0], "w:id") {
			t.Errorf("block %d opens bookmark %s and closes another one", i, id)
		}
	}
	if headings != 3 {
		t.Errorf("%d of the three headings carry a bookmark", headings)
	}
}

// TestAnAnchorLinkIsAJumpAndNotARelationship: an in-document jump is
// w:anchor with no relationship at all, and the link above the heading it
// names is the forward case the pre-walk exists for.
func TestAnAnchorLinkIsAJumpAndNotARelationship(t *testing.T) {
	out := walk(t, "See [below](#scope).\n\n## Scope\n")
	got := serialise(t, out.Blocks)

	if !strings.Contains(got, `<w:hyperlink w:anchor="_h_scope">`) {
		t.Errorf("the anchor link is no jump:\n%s", got)
	}
	if strings.Contains(got, "r:id=") {
		t.Errorf("the jump names a relationship:\n%s", got)
	}
	if len(out.Media) != 0 {
		t.Errorf("the walk recorded %d relationships, want none", len(out.Media))
	}
	link := find(out.Blocks[0], "w:hyperlink")
	if link == nil {
		t.Fatalf("the paragraph holds no w:hyperlink:\n%s", got)
	}
	if color := find(link, "w:color"); color == nil || attr(t, color, "w:val") != "1155cc" {
		t.Errorf("the jump's words are not in the link colour:\n%s", got)
	}
	if find(link, "w:u") == nil {
		t.Errorf("the jump's words are not underlined:\n%s", got)
	}
	for _, warning := range out.Warnings {
		if strings.Contains(warning, "#scope") {
			t.Errorf("a resolved anchor warns: %q", warning)
		}
	}
}

// TestAnAnchorToNoHeadingWarnsAndPrintsPlainText: a jump to nowhere is
// refused the way a code block is refused, named on the envelope and printed
// as the words the author wrote.
func TestAnAnchorToNoHeadingWarnsAndPrintsPlainText(t *testing.T) {
	out := walk(t, "See [below](#nowhere).\n")
	got := serialise(t, out.Blocks)

	if strings.Contains(got, "w:hyperlink") {
		t.Errorf("the dead anchor is still a link:\n%s", got)
	}
	if !strings.Contains(got, ">below<") {
		t.Errorf("the link's words are missing:\n%s", got)
	}
	if len(out.Media) != 0 {
		t.Errorf("the walk recorded %d relationships, want none", len(out.Media))
	}
	want := "line 1: the link to #nowhere names no heading in this note, so its words are printed as plain text"
	if !has(out.Warnings, want) {
		t.Errorf("the warnings are %v, want one reading %q", out.Warnings, want)
	}
}

// TestAFigureOnlyHeadingCarriesNoBookmark: a heading that is nothing but a
// picture emits no heading paragraph, so there is nothing to land on and a
// link naming it is as dead as a link naming no heading at all.
func TestAFigureOnlyHeadingCarriesNoBookmark(t *testing.T) {
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "pic.png"), pngBytes(t, 1, 1), 0o600); err != nil {
		t.Fatalf("write pic.png: %v", err)
	}
	out, err := Render(config(t), []byte("See [it](#altpicpng).\n\n## ![alt](pic.png)\n"), dir, true)
	if err != nil {
		t.Fatalf("Render: %v", err)
	}
	got := serialise(t, out.Blocks)

	if strings.Contains(got, "w:bookmarkStart") {
		t.Errorf("a figure-only heading carries a bookmark:\n%s", got)
	}
	if strings.Contains(got, "w:hyperlink") {
		t.Errorf("the link to a figure-only heading is a jump to nothing:\n%s", got)
	}
	if !strings.Contains(got, ">it<") {
		t.Errorf("the link's words are missing:\n%s", got)
	}
	want := "line 1: the link to #altpicpng names no heading in this note, so its words are printed as plain text"
	if !has(out.Warnings, want) {
		t.Errorf("the warnings are %v, want one reading %q", out.Warnings, want)
	}
}

// TestADeadAnchorInsideABlockQuoteNamesItsOwnLine: quoteBlock handles a
// top-level paragraph itself rather than through paragraphBlock, so it is the
// one walker path that has to set the current line for itself. Read off the
// block before it, the warning names the last heading and the author looks for
// the link there.
func TestADeadAnchorInsideABlockQuoteNamesItsOwnLine(t *testing.T) {
	out := walk(t, "# Purpose\n\n> See [below](#nowhere).\n")

	want := "line 3: the link to #nowhere names no heading in this note, so its words are printed as plain text"
	if !has(out.Warnings, want) {
		t.Errorf("the warnings are %v, want one reading %q", out.Warnings, want)
	}
}

// TestADeadAnchorInsideATableNamesTheTablesOwnLine: a cell is not a line the
// author would recognise, so the table branch sets the current line to the
// table's and every dead anchor in any of its cells names that. Read off the
// block before it, the warning names the last heading instead.
func TestADeadAnchorInsideATableNamesTheTablesOwnLine(t *testing.T) {
	out := walk(t, "# Purpose\n\n| a | b |\n| --- | --- |\n| See [below](#nowhere). | c |\n")

	want := "line 3: the link to #nowhere names no heading in this note, so its words are printed as plain text"
	if !has(out.Warnings, want) {
		t.Errorf("the warnings are %v, want one reading %q", out.Warnings, want)
	}
}

// has is one exact warning among the walk's, because a warning read with
// Contains passes on half a sentence.
func has(warnings []string, want string) bool {
	for _, warning := range warnings {
		if warning == want {
			return true
		}
	}
	return false
}

// TestOneDeadAnchorWarnsOnce: the check sits in addRuns, which runs once per
// run, and a link whose words carry mixed formatting is several runs. Warned
// per run, one dead link prints the identical sentence twice and the envelope
// says the note holds two of them. The sentence names a line and a
// destination and nothing else, so a second copy carries nothing.
func TestOneDeadAnchorWarnsOnce(t *testing.T) {
	out := walk(t, "# Purpose\n\nSee [**bold** and plain](#nowhere) here.\n")

	want := "line 3: the link to #nowhere names no heading in this note, so its words are printed as plain text"
	if got := count(out.Warnings, want); got != 1 {
		t.Errorf("the warnings are %v, want exactly one reading %q, got %d", out.Warnings, want, got)
	}
}

// TestTwoDeadAnchorsOnOneLineWarnOncePerDestination: two links on one line
// that jump nowhere are two separate sentences when they name different
// headings, and one when they name the same one, because the sentence the
// author reads would otherwise repeat itself word for word.
func TestTwoDeadAnchorsOnOneLineWarnOncePerDestination(t *testing.T) {
	out := walk(t, "# Purpose\n\nSee [a](#nowhere) and [b](#nowhere) and [c](#elsewhere).\n")

	same := "line 3: the link to #nowhere names no heading in this note, so its words are printed as plain text"
	other := "line 3: the link to #elsewhere names no heading in this note, so its words are printed as plain text"
	if got := count(out.Warnings, same); got != 1 {
		t.Errorf("the warnings are %v, want exactly one reading %q, got %d", out.Warnings, same, got)
	}
	if got := count(out.Warnings, other); got != 1 {
		t.Errorf("the warnings are %v, want exactly one reading %q, got %d", out.Warnings, other, got)
	}
}

// TestTheSameDeadAnchorOnTwoLinesWarnsTwice: the warning is deduplicated on
// the line as well as the destination, because two lines are two places the
// author has to go and fix.
func TestTheSameDeadAnchorOnTwoLinesWarnsTwice(t *testing.T) {
	out := walk(t, "# Purpose\n\nSee [a](#nowhere).\n\nAnd [b](#nowhere).\n")

	first := "line 3: the link to #nowhere names no heading in this note, so its words are printed as plain text"
	second := "line 5: the link to #nowhere names no heading in this note, so its words are printed as plain text"
	if !has(out.Warnings, first) || !has(out.Warnings, second) {
		t.Errorf("the warnings are %v, want one reading %q and one reading %q",
			out.Warnings, first, second)
	}
}

// count is how many of the walk's warnings read exactly want.
func count(warnings []string, want string) int {
	n := 0
	for _, warning := range warnings {
		if warning == want {
			n++
		}
	}
	return n
}

// TestAHeadingInsideAFootnoteIsNoAnchor: a footnote definition is dropped
// whole, so a heading written inside one reaches no paragraph and carries no
// bookmark. The pre-walk must not count its id either, or the link to it comes
// out live and jumps nowhere, which is the one failure this feature exists to
// prevent. The link falls to the dead-anchor branch instead and is named.
func TestAHeadingInsideAFootnoteIsNoAnchor(t *testing.T) {
	out := walk(t, "Body.[^1]\n\nSee [jump](#hidden-heading).\n\n[^1]: the detail\n\n    # Hidden heading\n")

	body := serialise(t, out.Blocks)
	if strings.Contains(body, `w:anchor="_h_hidden_heading"`) {
		t.Errorf("the body carries a live anchor to a heading inside a footnote, which no bookmark marks:\n%s", body)
	}
	want := "line 3: the link to #hidden-heading names no heading in this note, so its words are printed as plain text"
	if !has(out.Warnings, want) {
		t.Errorf("the warnings are %v, want one reading %q", out.Warnings, want)
	}
}

// TestTheAnchorViewWritesIsTheIDBodyCollects is the round trip the export and
// align skills rest on. `gdoc export` writes a link to a heading in the same
// file as "#" and view.Anchor of the heading's words; this package resolves
// such a link by looking its target up in headingAnchors, which holds the ids
// goldmark made. The two have to be one rule, so this test asks goldmark for
// the answer rather than stating one: a goldmark that changes its mind fails
// here rather than in somebody's document.
//
// The headings are the shapes that tell a hand-written slug rule from this one:
// punctuation between two spaces, two separators in a row, accents, a colon,
// and words that are only punctuation.
func TestTheAnchorViewWritesIsTheIDBodyCollects(t *testing.T) {
	for _, heading := range []string{
		"Scope",
		"Risk & Control <ampersands>",
		"Résumé of Änderungen: naïve café",
		"Hello -- world",
		"1-Scope",
		"Data, privacy and retention",
		"under_score and space",
		"+++",
		"Цели проекта",
		"1.1-Цели проекта",
	} {
		source := []byte("# " + heading + "\n")
		pc := parser.NewContext(parser.WithIDs(view.NewHeadingIDs()))
		ids, err := headingAnchors(parse().Parser().Parse(text.NewReader(source), parser.WithContext(pc)), source)
		if err != nil {
			t.Fatal(err)
		}

		if anchor := view.Anchor(heading); ids[anchor] == "" {
			t.Errorf("the heading %q is %v to goldmark and %q to view.Anchor",
				heading, anchorNames(ids), anchor)
		}
	}
}

// TestAProjectedHeadingsAnchorIsTheIDBodyCollects is the same round trip over
// the heading lines the projection itself writes rather than over plain words.
// It is the half that was missing: goldmark takes its id from the whole line,
// so a heading holding a hyperlink or a chip has an id the heading's text runs
// do not give, and every link to it in the exported file was dead.
//
// The lines are view's own output for those headings, not strings written out
// here, so a change to how a link or a chip is projected fails here rather than
// in somebody's note.
func TestAProjectedHeadingsAnchorIsTheIDBodyCollects(t *testing.T) {
	for _, line := range []string{
		"See [the policy](https://e.com)",
		"Risk [person: Ann] and Control",
		"Owner: [person: Ann]",
		"Scope and [the register](https://e.com/r)",
		"A [link: Q3 plan](https://drive.google.com/x) heading",
	} {
		source := []byte("# " + line + "\n")
		pc := parser.NewContext(parser.WithIDs(view.NewHeadingIDs()))
		ids, err := headingAnchors(parse().Parser().Parse(text.NewReader(source), parser.WithContext(pc)), source)
		if err != nil {
			t.Fatal(err)
		}

		if anchor := view.Anchor(line); ids[anchor] == "" {
			t.Errorf("the heading line %q is %v to goldmark and %q to view.Anchor",
				line, anchorNames(ids), anchor)
		}
	}
}

// anchorNames is the ids a map holds, for a failure to name.
func anchorNames(ids map[string]string) []string {
	out := make([]string, 0, len(ids))
	for id := range ids {
		out = append(out, id)
	}
	return out
}
